<?php
/** Integration test. Run: php tools/tests/formularios_http_test.php --qa-only
 * Writes only to 127.0.0.1:18079 and naser_qa_mejoras on 127.0.0.1:13379. */
if (PHP_SAPI !== 'cli' || !in_array('--qa-only', $argv ?? [], true)) {
 if (PHP_SAPI !== 'cli') http_response_code(404);
 exit("Solo CLI y con --qa-only: esta prueba crea registros QA.\n");
}
if (!extension_loaded('curl') || !extension_loaded('pdo_mysql')) throw new RuntimeException('Se requieren curl y pdo_mysql.');

$pdo=new PDO('mysql:host=127.0.0.1;port=13379;dbname=naser_qa_mejoras;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
if ($pdo->query('SELECT DATABASE()')->fetchColumn() !== 'naser_qa_mejoras') throw new RuntimeException('Base no autorizada: solo QA.');
$n=0;function ck(bool $ok,string $msg){global $n;if(!$ok)throw new RuntimeException('FAIL: '.$msg);$n++;echo 'OK: '.$msg.PHP_EOL;}
$base='http://127.0.0.1:18079';$jar=tempnam(__DIR__.'/../../logs','naser_qa_forms_');register_shutdown_function(static function()use($jar){if(is_file($jar))unlink($jar);});
function req(string $path,$data=null,bool $json=false):array{global $base,$jar;$c=curl_init($base.$path);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$jar,CURLOPT_COOKIEFILE=>$jar,CURLOPT_TIMEOUT=>20]);if($data!==null){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,$json?json_encode($data):http_build_query($data));if($json)curl_setopt($c,CURLOPT_HTTPHEADER,['Content-Type: application/json','X-CSRF-Token: '.($GLOBALS['csrf']??'')]);}$raw=curl_exec($c);if($raw===false)throw new RuntimeException(curl_error($c));$hs=curl_getinfo($c,CURLINFO_HEADER_SIZE);$body=substr($raw,$hs);$respuesta=['status'=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),'body'=>$body,'json'=>json_decode($body,true)];unset($c);return $respuesta;}
$prefix='qa-forms-'.bin2hex(random_bytes(5));$email=$prefix.'@example.test';$pass='QA-form-only-'.bin2hex(random_bytes(12));$pdo->prepare("INSERT INTO usuarios(nombre,email,password,rol,activo,recibe_mails,debe_cambiar_password) VALUES ('QA Forms',?,?,'admin',1,0,0)")->execute([$email,password_hash($pass,PASSWORD_DEFAULT)]);
$r=req('/php/login.php');preg_match('/name="csrf" value="([^"]+)"/',$r['body'],$m);$GLOBALS['csrf']=$m[1]??'';ck($r['status']===200&&$GLOBALS['csrf']!=='','Login and CSRF');$r=req('/php/login.php',['csrf'=>$GLOBALS['csrf'],'email'=>$email,'password'=>$pass]);ck($r['status']===302,'Authenticated QA admin');
$r=req('/php/formularios/api.php?sesion=1');ck($r['status']===200&&isset($r['json']['usuario_id'],$r['json']['csrf']),'Authenticated session renewal returns identity and CSRF');
$payload=['accion'=>'guardar','formulario'=>'hseq-minuta-reunion','client_token'=>bin2hex(random_bytes(20)),'referencia'=>$prefix,'datos'=>['#nombre'=>'Version inicial'],'storage'=>['lista'=>'[{"item":1}]']];
$r=req('/php/formularios/api.php');ck($r['status']===405,'GET without session action is rejected');
$bad=$payload;$bad['client_token']='short';$r=req('/php/formularios/api.php',$bad,true);ck($r['status']===400,'New draft requires a valid idempotency token');
$bad=$payload;$bad['datos']='not an object';$r=req('/php/formularios/api.php',$bad,true);ck($r['status']===400,'Scalar form data is rejected');
$oldCsrf=$GLOBALS['csrf'];$GLOBALS['csrf']='invalid-qa-csrf';$r=req('/php/formularios/api.php',$payload,true);ck($r['status']===403,'Invalid CSRF cannot create a form');$GLOBALS['csrf']=$oldCsrf;
$r=req('/php/formularios/api.php',$payload,true);ck($r['status']===200&&($r['json']['ok']??false),'Create draft');$id=(int)$r['json']['id'];$rev=(int)$r['json']['revision'];ck($rev===1,'Initial revision equals one');
$r=req('/php/formularios/api.php',$payload,true);ck($r['status']===200&&(int)$r['json']['id']===$id&&$r['json']['repetido']===true,'Creation retry returns same draft');ck((int)$r['json']['revision']===1,'Creation retry does not advance revision');
$noop=$payload+['id'=>$id,'revision'=>1];$r=req('/php/formularios/api.php',$noop,true);ck($r['status']===200&&(int)$r['json']['revision']===1,'Unchanged save does not advance revision');
$a=$payload+['id'=>$id,'revision'=>1];$a['datos']=['#nombre'=>'Guardado desde pestaña A'];$r=req('/php/formularios/api.php',$a,true);ck($r['status']===200&&(int)$r['json']['revision']===2,'First tab advances revision');
$b=$a;$b['datos']=['#nombre'=>'Cambios de pestaña B'];$r=req('/php/formularios/api.php',$b,true);ck($r['status']===409&&($r['json']['conflicto']??false),'Stale tab receives conflict');$actual=$pdo->query('SELECT * FROM formularios_registros WHERE id='.$id)->fetch();ck(json_decode($actual['datos_json'],true)['#nombre']==='Guardado desde pestaña A','Conflict preserves current server values');
$missing=$a;unset($missing['revision']);$r=req('/php/formularios/api.php',$missing,true);ck($r['status']===409,'Mutation requires revision');
$copy=$b;$copy['accion']='guardar_copia';$copy['client_token']=bin2hex(random_bytes(20));$r=req('/php/formularios/api.php',$copy,true);ck($r['status']===200&&$r['json']['id']!==$id,'Conflict can save independent copy');$copyId=(int)$r['json']['id'];ck(json_decode($pdo->query('SELECT datos_json FROM formularios_registros WHERE id='.$copyId)->fetchColumn(),true)['#nombre']==='Cambios de pestaña B','Local conflict data preserved in copy');ck((int)$pdo->query('SELECT revision FROM formularios_registros WHERE id='.$id)->fetchColumn()===2,'Copy never modifies original');
$r=req('/php/formularios/api.php',$copy,true);ck($r['status']===200&&(int)$r['json']['id']===$copyId&&$r['json']['repetido'],'Copy retry is idempotent');
$a['accion']='enviar';$a['revision']=2;$r=req('/php/formularios/api.php',$a,true);ck($r['status']===200&&$r['json']['estado']==='enviado'&&(int)$r['json']['revision']===3,'Submit draft with latest revision');
$r=req('/php/formularios/api.php',['accion'=>'guardar','id'=>$id,'revision'=>3,'datos'=>[],'storage'=>[]],true);ck($r['status']===403,'Submitted form cannot be edited');
$r=req('/php/formularios/api.php',['accion'=>'aprobar','id'=>$id,'revision'=>2],true);ck($r['status']===409,'Stale approval rejected');$r=req('/php/formularios/api.php',['accion'=>'aprobar','id'=>$id,'revision'=>3],true);ck($r['status']===200&&$r['json']['estado']==='aprobado'&&(int)$r['json']['revision']===4,'Current approval succeeds');
$r=req('/php/formularios/api.php',['accion'=>'reabrir','id'=>$id,'revision'=>4],true);ck($r['status']===200&&(int)$r['json']['revision']===5,'Reopen increments revision');
$before=(int)$pdo->query('SELECT COUNT(*) FROM formularios_historial WHERE registro_id='.$id)->fetchColumn();$r=req('/php/formularios/api.php',['accion'=>'eliminar','id'=>$id,'revision'=>5],true);ck($r['status']===200&&$r['json']['estado']==='papelera','Delete sends form to trash');$actual=$pdo->query('SELECT * FROM formularios_registros WHERE id='.$id)->fetch();ck($actual&&$actual['eliminado_lote']!==null&&(int)$actual['revision']===6,'Trash preserves row and version');ck((int)$pdo->query('SELECT COUNT(*) FROM formularios_historial WHERE registro_id='.$id)->fetchColumn()>=$before,'Trash preserves history');
$r=req('/php/formularios/llenar.php?id='.$id);ck($r['status']===404,'Trashed form unavailable in editor');$paper=(int)$pdo->query('SELECT id FROM papelera WHERE registro_id='.$id." AND tipo='formulario' ORDER BY id DESC LIMIT 1")->fetchColumn();$r=req('/php/admin/papelera.php',['csrf'=>$GLOBALS['csrf'],'accion'=>'restaurar','id'=>$paper]);ck($r['status']===302,'Restore from trash endpoint');$actual=$pdo->query('SELECT * FROM formularios_registros WHERE id='.$id)->fetch();ck($actual['eliminado_lote']===null&&(int)$actual['revision']===7,'Restore releases form with a new revision');
$r=req('/php/formularios/llenar.php?id='.$copyId);ck($r['status']===200&&str_contains($r['body'],'fxSaveStatus')&&str_contains($r['body'],'naser-autosave.js'),'Editor includes autosave and conflict interface');
$r=req('/php/formularios/api.php',$payload,true);ck($r['status']===409&&($r['json']['conflicto']??false),'An old creation retry cannot overwrite an edited or restored draft');
$changed=$copy;$changed['datos']=['#nombre'=>'Payload distinto con mismo token'];$r=req('/php/formularios/api.php',$changed,true);ck($r['status']===409,'Reusing a creation token with changed data requires a copy');
ck(json_decode($pdo->query('SELECT datos_json FROM formularios_registros WHERE id='.$copyId)->fetchColumn(),true)['#nombre']==='Cambios de pestaña B','Rejected token reuse preserves saved copy');
$r=req('/php/formularios/api.php?sesion=1');ck($r['status']===200&&is_int($r['json']['usuario_id'])&&$r['json']['csrf']===$GLOBALS['csrf'],'Session identity and CSRF remain available after mutations');
echo 'TOTAL: '.$n.' passed. QA marker: '.$prefix.PHP_EOL;
